// n8n Code node: "validate-csv"
// Mode: Run Once for All Items.   Language: JavaScript.
// Input:  read from the Webhook node by name (Turnstile + rate limit run in between).
// Output: one item whose json is the validation result (summary, byType, issues, cleaned).
//
// This is the same function the web page uses in preview mode, so you can compare
// the workflow's output with the preview's. Keep them in sync if you change one.

const body = $('Webhook').first().json.body || {};

// ---- input guard (the page checks these too, but never trust the browser) ----
const MAX_ROWS = 500;
const MAX_COLS = 20;
const MAX_CELL = 1000;
const fail = (msg) => { throw new Error('invalid_input: ' + msg); };

if (body.action !== 'validate_csv') fail('wrong action');
if (!Array.isArray(body.headers) || body.headers.length === 0 || body.headers.length > MAX_COLS) fail('headers');
if (!Array.isArray(body.rows) || body.rows.length === 0 || body.rows.length > MAX_ROWS) fail('rows');
const TYPES = ['text', 'email', 'phone', 'date', 'number', 'integer', 'url'];
for (const r of body.rules || []) {
  if (!TYPES.includes(r.type)) fail('unknown column type');
}
for (const row of body.rows) {
  if (!Array.isArray(row)) fail('row is not a list');
  for (const cell of row) {
    if (String(cell ?? '').length > MAX_CELL) fail('cell too long');
  }
}

function validateCsv(payload) {
  const MAX_ISSUES = 500
  const headers = Array.isArray(payload.headers) ? payload.headers.map(String) : []
  const inputRows = Array.isArray(payload.rows) ? payload.rows : []
  const options = payload.options || {}
  const trimOn = options.trimWhitespace !== false
  const dedupeOn = options.removeDuplicateRows === true
  const dateOrder = options.dateOrder === 'DMY' ? 'DMY' : 'MDY'

  const rules = headers.map((h, i) => {
    const r = (payload.rules || []).find((x) => x.index === i) || {}
    return { column: h, type: r.type || 'text', required: r.required === true, unique: r.unique === true }
  })

  const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/
  const MESSAGES = {
    required_missing: 'Required value is empty',
    invalid_email: 'Not a valid email address',
    invalid_phone: 'Not a valid phone number',
    invalid_date: 'Not a real date',
    invalid_number: 'Not a valid number',
    invalid_url: 'Not a valid web address',
    duplicate_value: 'Value should be unique but appears more than once',
    duplicate_row: 'Identical to an earlier row',
    whitespace: 'Extra spaces at the start or end',
    format_fixed: 'Reformatted to a standard form',
    column_count: 'Row has a different number of columns than the header',
  }
  const SEVERITY = { whitespace: 'warning', duplicate_row: 'warning', format_fixed: 'warning' }

  const pad = (n) => String(n).padStart(2, '0')
  function toIsoDate(v) {
    let y, m, d
    let match = v.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/)
    if (match) {
      y = +match[1]; m = +match[2]; d = +match[3]
    } else {
      match = v.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/)
      if (!match) return null
      y = +match[3]
      if (dateOrder === 'DMY') { d = +match[1]; m = +match[2] } else { m = +match[1]; d = +match[2] }
    }
    const date = new Date(Date.UTC(y, m - 1, d))
    const real = date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d
    return real ? `${y}-${pad(m)}-${pad(d)}` : null
  }

  const issues = []
  const counts = {}
  let issueTotal = 0
  const rowsWithErrors = new Set()
  const uniqueSeen = rules.map(() => new Map())
  const rowSeen = new Map()
  const cleanedRows = []
  const keptNos = []
  let duplicatesRemoved = 0

  function add(rowNo, col, value, type, suggestion, autoFixed) {
    const severity = SEVERITY[type] || 'error'
    issueTotal++
    counts[type] = (counts[type] || 0) + 1
    if (severity === 'error') rowsWithErrors.add(rowNo)
    if (issues.length < MAX_ISSUES) {
      issues.push({
        row: rowNo,
        column: col,
        value: String(value).slice(0, 80),
        type,
        severity,
        message: MESSAGES[type],
        suggestion: suggestion || '',
        autoFixed: autoFixed === true,
      })
    }
  }

  inputRows.forEach((rawRow, idx) => {
    const rowNo = idx + 1 // first data row is row 1; the header is not counted
    const cells = Array.isArray(rawRow) ? rawRow.map((c) => String(c ?? '')) : []
    if (cells.length !== headers.length) {
      add(rowNo, '', `${cells.length} columns, expected ${headers.length}`, 'column_count', 'Check for a missing or extra delimiter', false)
      while (cells.length < headers.length) cells.push('')
      cells.length = headers.length
    }

    const out = cells.map((raw, c) => {
      const rule = rules[c]
      const col = rule.column
      let value = raw

      const trimmed = raw.trim()
      if (trimmed !== raw) {
        add(rowNo, col, raw, 'whitespace', trimOn ? 'Spaces trimmed' : 'Trim the spaces', trimOn)
        if (trimOn) value = trimmed
      }

      const probe = value.trim()
      if (probe === '') {
        if (rule.required) add(rowNo, col, '', 'required_missing', 'Fill in this value', false)
        return value
      }

      if (rule.type === 'email' && !EMAIL.test(probe)) {
        add(rowNo, col, value, 'invalid_email', probe.includes('@') ? 'Check the domain part' : 'Add the @ and a domain', false)
      } else if (rule.type === 'phone') {
        const digits = probe.replace(/\D/g, '')
        if (!/^[+()\d\s.-]+$/.test(probe) || digits.length < 7 || digits.length > 15) {
          add(rowNo, col, value, 'invalid_phone', 'Use 7 to 15 digits, e.g. +63 917 123 4567', false)
        }
      } else if (rule.type === 'date') {
        const iso = toIsoDate(probe)
        if (!iso) {
          add(rowNo, col, value, 'invalid_date', 'Use YYYY-MM-DD', false)
        } else if (iso !== probe) {
          add(rowNo, col, value, 'format_fixed', `Standardised to ${iso}`, true)
          value = iso
        }
      } else if (rule.type === 'number' || rule.type === 'integer') {
        const plain = /^-?\d+(\.\d+)?$/
        const withCommas = /^-?\d{1,3}(,\d{3})+(\.\d+)?$/
        const intOnly = /^-?\d+$/
        if (withCommas.test(probe) && (rule.type === 'number' || intOnly.test(probe.replace(/,/g, '')))) {
          const fixed = probe.replace(/,/g, '')
          add(rowNo, col, value, 'format_fixed', `Removed thousands separators: ${fixed}`, true)
          value = fixed
        } else if (!(rule.type === 'integer' ? intOnly : plain).test(probe)) {
          add(rowNo, col, value, 'invalid_number', rule.type === 'integer' ? 'Use a whole number' : 'Use digits and an optional decimal point', false)
        }
      } else if (rule.type === 'url') {
        let ok = false
        try {
          const u = new URL(probe)
          ok = (u.protocol === 'http:' || u.protocol === 'https:') && u.hostname.includes('.')
        } catch (e) {
          ok = false
        }
        if (!ok) add(rowNo, col, value, 'invalid_url', 'Start with http:// or https://', false)
      }

      if (rule.unique) {
        const key = value.trim().toLowerCase()
        if (uniqueSeen[c].has(key)) {
          add(rowNo, col, value, 'duplicate_value', `Same as row ${uniqueSeen[c].get(key)}`, false)
        } else {
          uniqueSeen[c].set(key, rowNo)
        }
      }
      return value
    })

    const rowKey = out.map((v) => v.trim().toLowerCase()).join('\u0001')
    if (rowSeen.has(rowKey)) {
      add(rowNo, '', out.join(' | '), 'duplicate_row', dedupeOn ? `Removed (same as row ${rowSeen.get(rowKey)})` : `Same as row ${rowSeen.get(rowKey)}`, dedupeOn)
      if (dedupeOn) {
        duplicatesRemoved++
        return
      }
    } else {
      rowSeen.set(rowKey, rowNo)
    }
    cleanedRows.push(out)
    keptNos.push(rowNo)
  })

  const byType = Object.keys(counts)
    .map((type) => ({ type, count: counts[type], severity: SEVERITY[type] || 'error' }))
    .sort((a, b) => b.count - a.count)
  const autoFixed = issues.filter((i) => i.autoFixed).length

  return {
    summary: {
      rowsChecked: inputRows.length,
      rowsWithErrors: rowsWithErrors.size,
      cleanRows: keptNos.filter((n) => !rowsWithErrors.has(n)).length,
      issuesTotal: issueTotal,
      autoFixed,
      duplicatesRemoved,
    },
    byType,
    issues,
    truncated: issueTotal > issues.length,
    cleaned: { headers, rows: cleanedRows },
  }
}

return [{ json: validateCsv(body) }];

