// Run Once for All Items
const validation = $('validate-csv').first().json;
const ai = $input.first().json.output || {};
return [{ json: { ok: true, result: {
  ...validation,
  aiSummary: typeof ai.aiSummary === 'string' ? ai.aiSummary : '',
  topFixes: Array.isArray(ai.topFixes) ? ai.topFixes.slice(0, 5) : [],
} } }];

// Run Once for All Items
// Builds the "result" email. Returns NO items (so nothing is sent) when the
// visitor left the email box empty or typed something that is not an address.
const body = $('Webhook').first().json.body || {};
const to = String(body.notifyEmail || '').trim();
const valid = to.length > 0 && to.length <= 254 &&
  /^[^\s@<>(),;:"\\]+@[^\s@<>(),;:"\\]+\.[^\s@<>(),;:"\\]{2,}$/.test(to);
if (!valid) return [];

const r = $('merge').first().json.result;
const s = r.summary;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fileName = String(body.fileName || 'your file').replace(/[\r\n]+/g, ' ').slice(0, 80);
const clean = s.issuesTotal === 0;
const verdict = clean ? 'No problems found' : `${s.issuesTotal} issue${s.issuesTotal === 1 ? '' : 's'} found`;
const subject = `CSV check: ${fileName} - ${verdict}`;

const FONT = 'font-family:Arial,Helvetica,sans-serif;color:#202124;';
const h3 = (t) => `<h3 style="${FONT}font-size:17px;margin:26px 0 8px;">${esc(t)}</h3>`;
const li = (t) => `<li style="margin:6px 0;">${t}</li>`;
const mono = (t) => `<code style="background:#f1f3f4;padding:1px 5px;border-radius:3px;font-family:Consolas,monospace;font-size:12px;">${esc(t)}</code>`;

const stat = (label, n) => `<td style="padding:8px 14px 8px 0;${FONT}"><div style="font-size:22px;font-weight:bold;">${esc(n)}</div><div style="font-size:12px;color:#5f6368;">${esc(label)}</div></td>`;

const byType = (r.byType || []).slice(0, 12).map((t) =>
  li(`<b>${esc(String(t.type).replace(/_/g, ' '))}</b> (${esc(t.severity)}): ${esc(t.count)}`)).join('');

const fixes = (r.topFixes || []).map((f) => li(esc(f))).join('');

const issues = (r.issues || []).slice(0, 10).map((i) =>
  li(`Row ${esc(i.row)}, <b>${esc(i.column)}</b>: ${esc(i.message)}${i.value !== '' && i.value != null ? ' ' + mono(String(i.value).slice(0, 60)) : ''}${i.autoFixed ? ' <span style="color:#188038;">(auto-fixed)</span>' : ''}<br><span style="color:#5f6368;">${esc(i.suggestion || '')}</span>`)).join('');

const html = `<div style="${FONT}max-width:600px;font-size:14px;line-height:1.5;">
<h1 style="font-size:24px;margin:0 0 4px;">CSV check &middot; ${esc(fileName)}</h1>
<div style="font-size:13px;color:#5f6368;">${esc(verdict)}</div>
${r.aiSummary ? `<p style="margin:16px 0 0;">${esc(r.aiSummary)}</p>` : ''}
${h3('Summary')}
<table role="presentation" cellpadding="0" cellspacing="0"><tr>${stat('rows checked', s.rowsChecked)}${stat('clean rows', s.cleanRows)}${stat('rows with errors', s.rowsWithErrors)}${stat('auto-fixed', s.autoFixed)}${stat('duplicates removed', s.duplicatesRemoved)}</tr></table>
${byType ? h3('Issues by type') + `<ul style="padding-left:22px;margin:0;">${byType}</ul>` : ''}
${fixes ? h3('Top fixes') + `<ul style="padding-left:22px;margin:0;">${fixes}</ul>` : ''}
${issues ? h3('First issues') + `<ul style="padding-left:22px;margin:0;">${issues}</ul>` + (s.issuesTotal > 10 ? `<p style="font-size:12px;color:#5f6368;">Showing 10 of ${esc(s.issuesTotal)}. The full list and the cleaned CSV download are on the page.</p>` : '') : ''}
<hr style="border:none;border-top:1px solid #dadce0;margin:28px 0 10px;">
<p style="font-size:12px;color:#5f6368;margin:0;">Sent from the Testarosa Playground demo. The checks are plain code; the summary is an AI suggestion. Verify before acting. Your file was not stored.</p>
</div>`;

return [{ json: { to, subject, html } }];
